local Drag=false
local Start
local Pos

Conn(Main.InputBegan:Connect(function(i)
    if i.UserInputType==Enum.UserInputType.MouseButton1
    or i.UserInputType==Enum.UserInputType.Touch then
        Drag=true
        Start=i.Position
        Pos=Main.Position
    end
end))

Conn(UIS.InputChanged:Connect(function(i)
    if not Drag then return end

    if i.UserInputType~=Enum.UserInputType.MouseMovement
    and i.UserInputType~=Enum.UserInputType.Touch then
        return
    end

    local d=i.Position-Start

    Main.Position=UDim2.new(
        Pos.X.Scale,
        Pos.X.Offset+d.X,
        Pos.Y.Scale,
        Pos.Y.Offset+d.Y
    )
end))

Conn(UIS.InputEnded:Connect(function(i)
    if i.UserInputType==Enum.UserInputType.MouseButton1
    or i.UserInputType==Enum.UserInputType.Touch then
        Drag=false
    end
end))

Conn(RS.Heartbeat:Connect(function()
    if not Running then return end

    local c=Pl.Character
    local root=c and c:FindFirstChild("HumanoidRootPart")

    if root and S.LockY then
        local p=root.Position

        if math.abs(p.Y-S.LockedY)>.1 then
            root.CFrame=CFrame.new(
                p.X,
                S.LockedY,
                p.Z
            )*root.CFrame.Rotation
        end

        local v=root.AssemblyLinearVelocity

        root.AssemblyLinearVelocity=Vector3.new(
            v.X,
            0,
            v.Z
        )
    end

    Distance()
end))

task.spawn(function()
    while Running do
        if S.Shooting then
            Shoot()
            task.wait(S.ShootDelay)
        else
            task.wait(.05)
        end
    end
end)

task.spawn(function()
    while Running do
        if S.AutoSkip then
            local r=R:FindFirstChild("Remotes")
            local s=r and r:FindFirstChild("SkipWave")

            if s then
                pcall(function()
                    if s:IsA("RemoteFunction") then
                        s:InvokeServer()
                    elseif s:IsA("RemoteEvent") then
                        s:FireServer()
                    end
                end)
            end

            task.wait(.05)
        else
            task.wait(.1)
        end
    end
end)

task.spawn(function()
    while Running do
        if S.WalkSpeed40 then
            local c=Pl.Character
            local h=c and c:FindFirstChildOfClass("Humanoid")

            if h then
                h.WalkSpeed=40
            end

            task.wait(1)
        else
            task.wait(.1)
        end
    end
end)

